  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lolaslashes.com/pages/affiliate-programme-terms-and-conditions', 'official_site', 'affiliate', 'The brand''s own affiliate programme terms (fetched) govern its ''Referral Partner Programme'': registration runs on its Refersion portal (lolaslashes.refersion.com) and partners earn a Referral Fee of 10% of the net value of each referred product purchase (excluding VAT and shipping), paid by bank transfer or PayPal within 30 days of a valid invoice. The terms contain no statement capping total earnings, so the cap is recorded as unknown; no creator-count figure is published, so saturation is recorded as unknown.', 'verified', now());
