  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 7, 7, 8, 5, '{"niche_fit": "Hair-growth serums and scalp care are high-engagement topics for haircare creators.", "ugc_evidence": "A live Awin program with a personal tracking dashboard; no dedicated creator cohort details are published.", "compensation": "Only a ceiling (''up to 10%'') is published and other directories differ (7%, 5-10%), so the rate is null; no cap statement is published.", "contact_access": "Applications run through Awin; no direct program email is published.", "opportunity_availability": "Open Awin program with roughly a one-month cookie.", "credibility": "Part of a major UK beauty retail group with international distribution."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Aritzia', 'https://www.aritzia.com', 'Canadian women''s fashion retailer founded in Vancouver in 1984, selling its own in-house labels — Wilfred, Babaton, TNA, Wilfred Free and the Super Puff outerwear line — through aritzia.com and boutiques across Canada and the US, positioned as ''everyday luxury'' with premium workwear, tailoring and cold-weather pieces.', 'Canada', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://linkapprove.com/affiliate-programs/aritzia-affiliate-program', 'https://linkapprove.com/affiliate-programs/aritzia-affiliate-program', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'LinkApprove', 6, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkapprove.com/affiliate-programs/aritzia-affiliate-program.', 'https://linkapprove.com/affiliate-programs/aritzia-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Aritzia Affiliate Program (via LinkApprove)', 'https://linkapprove.com/affiliate-programs/aritzia-affiliate-program', 'https://linkapprove.com/affiliate-programs/aritzia-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/aritzia-affiliate-program', 'affiliate_network', 'affiliate', 'LinkApprove''s program page (reviewed 2026-08-19 by its partnerships team) lists the Aritzia affiliate program at 6% per sale with a 14-day cookie window, available to LinkApprove creators and publishers in the US and Canada with no separate Aritzia application; average order value on the program is $180.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/aritzia-affiliate-program', 'affiliate_network', 'ugc_collab', 'LinkApprove recruits creators and publishers for the program from 1,000 followers, states that social and short-form video traffic is accepted across its fashion programs, and names North American workwear, outerwear and Canadian style creators as the best fit for Aritzia.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.aritzia.com', 'official_site', 'general', 'Aritzia''s official homepage sells women''s fashion under its own labels, leading with The Super Puff, sweatfleece, sweaters and activewear, and describes the brand as ''Everyday Luxury''.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 12, 10, 9, 5, '{"compensation": "A published 6% per sale on a high $180 average order value is solid mid-range fashion pay, though the 14-day cookie is short.", "contact_access": "A single platform route (LinkApprove account, decision usually within two business days) but no direct brand application page or published partnerships email.", "credibility": "Established 1984 Canadian retailer with a large boutique network and a premium public brand.", "niche_fit": "Pure women''s fashion with cult in-house labels (Wilfred, Babaton, TNA, Super Puff) that fashion creators already build content around \u2014 near the top of the fashion UGC niche.", "opportunity_availability": "Open to creators from 1,000 followers in the US and Canada with no separate brand application; limited only by the North-America-only shipping footprint.", "ugc_evidence": "The program is explicitly sold to creators and publishers, accepts social and short-form video traffic, and LinkApprove names workwear, outerwear and Canadian style creators as proven fits."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Michael Kors', 'https://www.michaelkors.com', 'American luxury fashion house founded by designer Michael Kors in 1981, selling handbags, watches, footwear, jewellery, eyewear, fragrance and men''s and women''s ready-to-wear under the Michael Kors Collection, MICHAEL Michael Kors and Michael Kors Mens labels through its own stores and website worldwide.', 'United States', 'published') returning id into bid;
