  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Michael Kors EU Affiliate Programme (Awin)', 'https://ui.awin.com/merchant-profile/15215', 'https://ui.awin.com/merchant-profile/15215', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/15215', 'affiliate_network', 'affiliate', 'Michael Kors'' own Awin EU merchant profile (fetched first-hand) publishes the program''s standard rate as 5% for full-price and 3% for markdown (excluding gift cards, shipping and VAT) with a 30-day cookie; the EU account is live in the Netherlands, Poland, Portugal and Belgium.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.postaffiliatepro.com/affiliate-program-directory/michael-kors-affiliate-program/', 'listing', 'compensation', 'US listings describe a separate CJ Affiliate program for the USA and Canada at around 2% with no minimum payout, and LinkApprove lists up to 7% — the recorded 5% is the Awin EU profile''s published standard rate, with the US figure treated as a regional-program difference rather than a conflict.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/15215', 'affiliate_network', 'general', 'The Awin profile describes Michael Kors as a world-renowned designer of luxury accessories and ready-to-wear, established in 1981, producing accessories, footwear, watches, jewellery, ready-to-wear, eyewear and fragrance.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 10, 8, 8, 5, '{"compensation": "5% standard on full-price sales in the EU program is mid-range for luxury; markdown pays 3% and the separate US program is reported lower at around 2%.", "contact_access": "Application is through the Awin merchant profile; no published partnerships email or direct creator application page was found.", "credibility": "Established 1981 luxury house with global retail presence and sustained international advertising.", "niche_fit": "Global luxury fashion and accessories brand with handbags and watches that anchor fashion and styling content.", "opportunity_availability": "Open application through Awin for the EU program (four live countries) and through CJ in North America, subject to network approval.", "ugc_evidence": "The program runs through major creator-accessible networks (Awin in the EU, CJ in North America) and the brand is a staple of luxury haul and styling content, though it publishes no creator-specific program page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ALDO', 'https://www.aldoshoes.com', 'Montreal-based footwear and accessories retailer founded in 1972, selling on-trend shoes, boots, sandals, handbags and accessories for men and women at accessible prices through aldoshoes.com and stores internationally.', 'Canada', 'published') returning id into bid;
