  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/aldo/', 'listing', 'affiliate', 'LinkClicky''s affiliate directory (updated March 10, 2024) lists the ALDO affiliate program on Rakuten Advertising for the CA and US regions at 6% per sale, described as the rate officially listed with the program, with application through Rakuten''s signup.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/aldo/', 'listing', 'compensation', 'Lasso''s directory lists the Aldo USA program at 5% per sale with a 15-day cookie, which conflicts with LinkClicky''s 6% officially-listed figure, so no single commission rate is recorded; the program itself is not in doubt.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/aldo/', 'listing', 'general', 'LinkClicky describes ALDO as a Montreal-based company founded in 1972 that has grown into an internationally recognized brand for on-trend shoes, accessories and handbags.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 8, 7, 8, 5, '{"compensation": "Published figures exist (5\u20136% per sale) but two directories conflict on the exact rate, so compensation is scored on the existence of a real percentage program with the rate left unrecorded.", "contact_access": "Joining is via the Rakuten Advertising network signup; no published brand partnerships email or creator application page was found.", "credibility": "Established 1972 Montreal retailer with international store presence.", "niche_fit": "Mass-market footwear and accessories with constant new styles \u2014 a natural fit for shoe, outfit and haul creators.", "opportunity_availability": "Open network application for US and Canadian publishers, subject to Rakuten and advertiser approval.", "ugc_evidence": "The Rakuten program is open to publishers and influencers and ALDO is a frequent subject of fashion content, but no creator-specific program page or ambassador structure is published."}'::jsonb);
