  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/allsaints/', 'listing', 'affiliate', 'Lasso''s directory lists the AllSaints affiliate program on Awin at 7% per sale with a 30-day cookie (its US listing shows 6.4%, a blended figure), corroborating Awin as the network and 7% as the standard rate.', 'publicly_reported', now());
