  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 13, 7, 7, 5, '{"compensation": "7% default commission (12.5% on gift cards) on premium price points is above the fashion-network norm.", "contact_access": "Application is through Awin with manual review; the programme names an account contact but publishes no email for creators.", "credibility": "Established 1994 London brand with stores across Europe and North America.", "niche_fit": "Iconic leather jackets and edgy premium styling give fashion creators a distinctive, high-basket product story.", "opportunity_availability": "Open to apply through Awin but every application is reviewed before acceptance, and voucher-code sites face lower rates.", "ugc_evidence": "A long-running affiliate programme with banners, product feed and cross-programme tracking across FR/DE/ES, and a brand heavily featured in styling content; applications are individually reviewed."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Decathlon', 'https://www.decathlon.com', 'French sporting goods retailer founded in 1976 near Lille, designing and selling affordable apparel, footwear and equipment for more than 70 sports — including hiking, camping, cycling, running and fitness — through over 1,500 stores in more than 55 countries and its own websites.', 'France', 'published') returning id into bid;
