  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Decathlon UK Affiliate Programme (Awin)', 'https://ui.awin.com/merchant-profile/26895', 'https://ui.awin.com/merchant-profile/26895', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/26895', 'affiliate_network', 'affiliate', 'Decathlon UK''s own Awin merchant profile (fetched first-hand) publishes the programme terms: 3% for all non-incentive publishers and 1% for incentive publishers, including sale and clearance products, a 30-day cookie period, mobile and app tracking, no commission on marketplace products, and states Decathlon works with all publisher types.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/decathlon/', 'listing', 'compensation', 'Rates vary by regional program: Lasso lists Decathlon at 6% per sale with a 14-day cookie for its program, and UpPromote reports US/Canada rates up to 10% by category; the recorded 3% is the standard content-publisher rate published on the UK Awin profile.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/26895', 'affiliate_network', 'general', 'The Awin profile records Decathlon as established in 1976 near Lille, France, now present in over 55 countries with more than 1,500 stores, covering over 70 sports under one roof.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 8, 8, 9, 5, '{"compensation": "3% for content publishers in the UK program is modest; some regional programs pay more (up to 10% by category in North America), and incentive publishers earn only 1%.", "contact_access": "Application via the Awin profile and the profile invites contact and product-review requests, though it names a contact without publishing an email.", "credibility": "Established 1976 global retailer with more than 1,500 stores in over 55 countries.", "niche_fit": "Huge multi-sport apparel and gear range at low prices suits outdoor, running, cycling and budget-gear creators, though it is sports retail rather than pure fashion.", "opportunity_availability": "Open to all publisher types through Awin with regional programs across Europe and North America.", "ugc_evidence": "The UK programme works with all publisher types and offers product-review requests, but publishes no creator-specific tier or ambassador structure."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Hertz', 'https://www.hertz.com', 'Global car rental company founded in 1918, offering cars, SUVs, luxury Dream Collection vehicles and vans for business and leisure rental at airport and city locations worldwide, booked through hertz.com and its app.', 'United States', 'published') returning id into bid;
