  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/hertz/', 'listing', 'compensation', 'Lasso''s directory corroborates 3% per sale for the Hertz program and lists a very short 24-hour cookie duration; a separate CJ Europe programme shows a 5% default for car bookings, treated as a regional variant.', 'publicly_reported', now());
