  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 8, 7, 8, 5, '{"compensation": "3% per completed rental is workable on high rental values, but the roughly 24-hour cookie window is among the shortest in travel and limits creator earnings.", "contact_access": "Joining is through CJ Affiliate; no published partnerships email or creator application page was found.", "credibility": "Century-old global rental brand with locations in airports and cities worldwide.", "niche_fit": "Car rental is a standard monetizable step in road-trip, itinerary and destination content for travel creators.", "opportunity_availability": "Open network application for US publishers, with a separate European programme also on CJ.", "ugc_evidence": "The CJ program supplies banners, text links and promotions to publishers and influencers, but there is no creator-specific program structure."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Avis', 'https://www.avis.com', 'Global car rental company operating in around 165 countries with more than 5,000 locations, renting cars, SUVs and premium vehicles to business and leisure travelers at airports and neighborhood locations, booked through avis.com.', 'United States', 'published') returning id into bid;
