  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkwhisper.com/car-affiliate-programs/', 'listing', 'affiliate', 'LinkWhisper''s car affiliate guide (fetched first-hand) states the Avis Car Rental affiliate program is run through Partnerize and offers a commission of up to 4% with incentives to boost earnings by car, date or location; the exact base depends on rental length and mileage, high performers can negotiate higher rates, and a Partnerize account is required before applying.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/avis/', 'listing', 'compensation', 'Lasso''s directory lists the Avis affiliate program at 4% per sale; cookie duration reports conflict across directories (1 day on Lasso versus 30–90 days elsewhere), so no cookie figure is treated as settled.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkwhisper.com/car-affiliate-programs/', 'listing', 'general', 'LinkWhisper describes Avis as a car rental company operating around the world, catering to business and leisure travelers at airport and off-airport locations.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 10, 7, 8, 5, '{"compensation": "4% of rental revenue with location/date incentives and negotiable rates for high performers is at the better end of car-rental affiliate pay, though the exact base varies with rental length and mileage.", "contact_access": "Application is through Partnerize; no published partnerships email was found on the sources checked.", "credibility": "Established global rental brand operating in around 165 countries.", "niche_fit": "A default car-rental option in travel itineraries and road-trip content, with premium and business ranges that suit several travel creator styles.", "opportunity_availability": "Open application through Partnerize for publishers, with global rental inventory behind it.", "ugc_evidence": "The Partnerize program provides regularly updated banners and creative in standard sizes for publishers; no creator-specific tier is published."}'::jsonb);
