  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Europcar International UK and Ireland Affiliate Programme (Awin)', 'https://ui.awin.com/merchant-profile/6795', 'https://ui.awin.com/merchant-profile/6795', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/6795', 'affiliate_network', 'affiliate', 'Europcar International''s UK and Ireland Awin merchant profile (fetched first-hand) publishes a standard commission of 6% of net sales, with affinity/influence, text-link and media-site channels authorized, monthly sales validation and an average advertiser payment period of 60 days; it also warns of partial post-deduplication with an average rejection rate around 40%.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/6795', 'affiliate_network', 'contact', 'The Awin profile publishes two program contacts for more information: andrea.savasta@awin.com and mouna.saidi@awin.com.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/europcar/', 'listing', 'compensation', 'LinkClicky lists a conflicting US figure of $7 flat per sale on Awin; the recorded 6% follows the network''s own current UK and Ireland merchant profile, and the flat-fee listing is documented here as a conflict.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/6795', 'affiliate_network', 'general', 'The profile describes Europcar as a major global vehicle rental company offering short- and long-term mobility solutions, including cars, vans and subscription services, under a multi-brand strategy with a global network.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 9, 12, 13, 7, 5, '{"compensation": "6% of net sales is the highest standard rate among the big car-rental programs, tempered by post-deduplication and a high average rejection rate disclosed on the profile.", "contact_access": "Two named program contacts with published emails on the network profile \u2014 unusually direct access for a rental brand.", "credibility": "Leading European rental operator within the Europcar Mobility Group, present in more than 140 countries.", "niche_fit": "Europe''s leading rental network is a strong fit for European road-trip and destination creators, narrower for US-only audiences.", "opportunity_availability": "Open application through Awin with manual review; the profile warns low-converting publishers risk suspension.", "ugc_evidence": "The programme explicitly authorizes affinity/influence channels and offers banner kits and advance offer information, but is publisher-led rather than creator-structured."}'::jsonb);
