  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 9, 12, 8, 5, '{"compensation": "3% default is modest, but on a \u00a31,650 average order value it is roughly \u00a350 per booking, and new-customer sales pay an enhanced 8%.", "contact_access": "A named program contact with a published email on the network profile, plus application through Awin.", "credibility": "Established 1981 UK tour operator describing itself as one of the most trusted in its market.", "niche_fit": "Small-group adventure tours across 120 countries map directly onto hiking, trekking, cycling and slow-travel creator content.", "opportunity_availability": "Open application through Awin with a 45-day cookie, a longer window than most travel programs.", "ugc_evidence": "A published affiliate programme with generic and offer creative and phone tracking, aimed at publishers whose audiences match its adventurous demographic; no creator tier is published."}'::jsonb);
