  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creality.com/resources/affiliate-program', 'official_site', 'affiliate', 'Creality''s official affiliate page runs the program on two networks - Impact (recommended for new creator partners) and Awin (for existing and preferred publishers) - with monthly payouts, performance tiers, a dedicated affiliate manager and early product access; the page publishes no commission rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creality.com/resources/affiliate-program', 'official_site', 'ugc_collab', 'The official page explicitly recruits content creators - YouTube, TikTok and Instagram creators and bloggers are a named partner category - alongside review websites, tech media and maker/STEM communities.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://en.wikipedia.org/wiki/Creality', 'listing', 'general', 'Wikipedia lists Shenzhen Creality 3D Technology Co., Ltd. as a Chinese 3D printer manufacturer founded in 2014 and headquartered in Shenzhen, selling consumer and industrial-grade 3D printers.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creality.com/resources/affiliate-program', 'official_site', 'compensation', 'No commission rate is published on the official program page, and third-party directories quote conflicting figures for the program, so no rate is recorded; no earnings cap or creator count is published either, so cap and saturation are recorded as unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 8, 12, 9, 5, '{"compensation": "No rate is published on the official page and directory figures conflict, so compensation scores low despite performance tiers being advertised.", "contact_access": "Two open network application routes (Impact and Awin) from one official program page, plus a named dedicated affiliate manager - strong access, just short of a public direct email.", "credibility": "One of the world''s leading consumer 3D printing brands, founded 2014 in Shenzhen, with millions of printers shipped globally.", "niche_fit": "Consumer 3D printers, scanners and engravers are core maker/creator tech - product demos, builds and reviews are a staple of tech UGC.", "opportunity_availability": "Applications are publicly open on both networks with monthly payouts; approval is still required, so not a perfect score.", "ugc_evidence": "The brand''s own program page names TikTok, YouTube and Instagram creators as a partner category and offers them early product access and a dedicated affiliate manager."}'::jsonb);
