  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 12, 13, 8, 4, '{"compensation": "A clear published rate - 8% on all qualifying purchases with a 30-day cookie - puts compensation in the upper-middle band.", "contact_access": "A named affiliate contact email published on the network profile plus an open Awin application - top-band access.", "credibility": "Large global charging brand (40M+ users, 174 countries) founded in 2014, though less premium-positioned than the biggest accessory names.", "niche_fit": "Power banks and fast chargers are staple, highly demonstrable creator tech accessories with broad everyday appeal.", "opportunity_availability": "Open application on Awin with a stated 2-3 business day review.", "ugc_evidence": "The Awin profile welcomes creators and bloggers by name, and the brand actively features creator product videos on its social channels."}'::jsonb);
