  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Le Creuset Affiliate Program (Pepperjam)', 'https://affi.io/m/le-creuset', 'https://affi.io/m/le-creuset', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affi.io/m/le-creuset', 'affiliate_network', 'affiliate', 'The Le Creuset program page reproduces the brand''s US affiliate terms: the program runs on Pepperjam, is US-traffic only, and advertises earnings of ''up to 10%'' commission - a ceiling rather than a flat rate, so no rate is recorded; social media promotion is allowed only case-by-case with program-manager approval.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affi.io/m/le-creuset', 'affiliate_network', 'general', 'The program page''s brand history states Le Creuset was founded in 1925 in Fresnoy-Le-Grand, France, still produces all enameled cast iron cookware in the original foundry, and is sold in more than 60 countries.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/lecreuset-com-affiliate-program', 'affiliate_network', 'compensation', 'Shopper''s listing quotes a 1.86% payout for Lecreuset, which conflicts with the Pepperjam program''s ''up to 10%'' ceiling, confirming no single published rate can be recorded; no earnings cap or creator count is published, so both are unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 8, 8, 7, 5, '{"compensation": "Only an ''up to 10%'' ceiling is published and another listing conflicts at 1.86%, so the rate is unrecorded and compensation scores mid-low.", "contact_access": "Application runs through the Pepperjam network; no public brand-side affiliate email was found.", "credibility": "Century-old premium cookware brand, founded 1925 in France and sold in 60+ countries - maximum credibility.", "niche_fit": "Iconic premium cookware is a centerpiece of food and home creator content, even though the brand skews classic rather than creator-first.", "opportunity_availability": "Open to US-traffic affiliates via Pepperjam, with approval and channel restrictions (social case-by-case).", "ugc_evidence": "A long-running affiliate program exists, but the terms allow social media promotion only case-by-case, so creator evidence is modest."}'::jsonb);
