  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nulo.com/social-ambassador-program', 'official_site', 'ugc_collab', 'Nulo''s official Social Ambassador Program page (''Team Nulo'') recruits pet-parent athletes and creators: perks include opportunities for exclusive paid campaigns, potential bonus payments for whitelisting opportunities, a monthly product supply and featured content opportunities across Nulo''s channels.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nulo.com/social-ambassador-program', 'official_site', 'compensation', 'The program FAQ states ambassadors ''earn free product and direct cash'' and requires athletes with at least 1,000 engaged followers; the program is US-only. No commission rate, earnings cap or cohort size is published, so the rate is unrecorded and cap/saturation are unknown - the 1,000-follower floor is an eligibility bar, not evidence of a small cohort.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 8, 10, 7, 5, '{"compensation": "Paid campaigns and direct cash are promised on the brand''s own page, but no rate or commission structure is published, so compensation scores mid-low.", "contact_access": "A public application page on the brand''s own domain; no public email contact was found.", "credibility": "Established premium pet food brand with national retail distribution.", "niche_fit": "Premium pet nutrition for active dogs and cats maps directly onto pet-parent creator content.", "opportunity_availability": "Applications are public but the program targets pet-parent athletes with at least 1,000 engaged followers and is US-only, narrowing availability.", "ugc_evidence": "A formal, public ambassador program with defined perks, featured-content opportunities and community calls - strong structured creator evidence."}'::jsonb);
